export default function Paragraph() {
  return (
    <div className="content-stretch flex flex-col items-start pb-[var(--spacing\/paragraph-spacing,16px)] relative size-full" data-node-id="13928:8370" data-name="Paragraph">
      <p className="[word-break:break-word] font-['Neue_Haas_Unica_W1G:Regular'] leading-[0] min-w-full not-italic relative shrink-0 text-[15px] text-[color:var(--UIColor.tui.text.primary,#333)] w-[min-content]" data-node-id="I13928:8370;9459:12596">
        <span className="leading-[24px]">{`В отличие от других платформ, iOS использует иной тип токенов при изменении межстрочного интервала. Поэтому в группе `}</span>
        <span className="font-['Neue_Haas_Unica_W1G:Bold'] leading-[24px]">Body</span>
        <span className="leading-[24px]">{` для `}</span>
        <span className="font-['Neue_Haas_Unica_W1G:Bold'] leading-[24px]">iosValue</span>
        <span className="leading-[24px]">{` появляется дополнительный ключ `}</span>
        <span className="font-['Neue_Haas_Unica_W1G:Bold'] leading-[24px]">respectsFontLineHeight</span>
        <span className="leading-[24px]">, который определяет, нужно ли применять нестандартное значение line-height.</span>
      </p>
    </div>
  );
}

export default function Paragraph() {
  return (
    <div className="content-stretch flex flex-col items-start pb-[var(--spacing\/paragraph-spacing,16px)] relative size-full" data-node-id="12472:11604" data-name="Paragraph">
      <p className="[word-break:break-word] font-['Neue_Haas_Unica_W1G:Regular'] leading-[0] min-w-full not-italic relative shrink-0 text-[15px] text-[color:var(--UIColor.tui.text.primary,#333)] w-[min-content]" data-node-id="I12472:11604;9459:12596">
        <span className="leading-[24px]">{`В iOS (UIKit / SwiftUI) `}</span>
        <span className="leading-[24px]">используются</span>
        <span className="leading-[24px]">{` динамические стили текста (Dynamic Type Text Styles). Это не про конкретный размер шрифта, а про семантические категории, которые автоматически масштабируются в зависимости от настроек пользователя`}</span>
      </p>
    </div>
  );
}

export default function Paragraph() {
  return (
    <div className="content-stretch flex flex-col items-start pb-[var(--spacing\/paragraph-spacing,16px)] relative size-full" data-node-id="12478:11607" data-name="Paragraph">
      <p className="[word-break:break-word] font-['Neue_Haas_Unica_W1G:Regular'] leading-[0] min-w-full not-italic relative shrink-0 text-[15px] text-[color:var(--UIColor.tui.text.primary,#333)] w-[min-content]" data-node-id="I12478:11607;9459:12596">
        <span className="leading-[24px]">{`Чтобы разные размеры текста корректно соотносились с системными шрифтами, для каждого шрифта в токенах TUI задан дополнительный параметр `}</span>
        <span className="font-['Neue_Haas_Unica_W1G:Medium'] leading-[24px]">textStyle</span>
        <span className="leading-[24px]">, подобранный максимально близко к соответствующему системному размеру шрифта</span>
      </p>
    </div>
  );
}
